Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='landreadsdone', at=datetime(2026, 11, 17, 0, 0, 0), actor='assistant', title='A land that writes several repositories reads done from what each holds', body="A land that writes three repositories (the code, its publication, the roadmap) keeps no marker of its own progress. Each step is skipped exactly when the repository it writes already holds its result: a tag, a publication row, a completed todo, a `Shipped:` trailer. So the repair of a land cut short is the land's own last steps, run again by the next train command.", rationale="A local marker says a step ran, not that its result is where a reader looks; the first design kept markers under the train's state and a failed record needed a command of its own.", supersedes=()))